public boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Ensure we have enough vertices to form a clique
    if (vertices.size() < 2) {
        return vertices.isEmpty();
    }

    // Find the maximum degree
    int maxDegree = 0;
    for (V vertex : vertices) {
        int degree = graph.degree(vertex);
        if (degree > maxDegree) {
            maxDegree = degree;
        }
    }

    // Only vertices with a degree of at least maxDegree (one degree less than the maxDegree of any vertex in the graph)
    Set<V> verticesToAdd = new HashSet<>(vertices);
    verticesToAdd.removeAll(graph.vertices);
    for (V vertex : verticesToAdd) {
        int degree = graph.degree(vertex);
        if (degree < maxDegree - 1) {
            return false;
        }
    }

    // Perform a check to confirm all vertices involved are connected
    for (V vertex : vertices) {
        Set<V>Neighbors = graph.neighbors(vertex);
        if (!neighbors.containsAll(vertices)) {
            return false;
        }
    }

    return true;
}

